namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int MaxRatePoints = 10;

    public int For(int subtotalCents)
    {
        return subtotalCents;
    }

    public int For(string tier, int subtotalCents)
    {
        var baseRate = tier switch
        {
            "Bronze" => 5,
            "Silver" => 7,
            "Gold" => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, "Unapproved loyalty tier.")
        };

        var bonus = subtotalCents >= 20000 ? 3 : subtotalCents >= 5000 ? 1 : 0;
        var rate = Math.Min(baseRate + bonus, MaxRatePoints);

        // Integer division drops any part cent.
        var discount = (int)((long)subtotalCents * rate / 100);
        return subtotalCents - discount;
    }
}
E
